import {testIdProps} from '@github-ui/test-id-props'

interface PermissionHeaderProps {
  appMode: 'edit' | 'create' | null
}

export function PermissionHeader({appMode}: PermissionHeaderProps) {
  const getDescriptionText = () => {
    if (appMode === null) {
      return (
        <p data-view-component="true" className="mb-3">
          Choose the minimal permissions necessary for your needs.{' '}
          <a
            target="_blank"
            rel="noopener noreferrer"
            className="Link--inTextBlock"
            href="https://docs.github.com/rest/overview/permissions-required-for-fine-grained-personal-access-tokens"
          >
            Learn more about permissions.
          </a>
        </p>
      )
    } else {
      return (
        <>
          <p data-view-component="true" className="mb-3">
            User permissions are granted on an individual user basis as part of the{' '}
            <a
              target="_blank"
              rel="noopener noreferrer"
              className="Link--inTextBlock"
              href="https://docs.github.com/apps/building-github-apps/identifying-and-authorizing-users-for-github-apps/#identifying-and-authorizing-users-for-github-apps"
            >
              User authorization flow.
            </a>
            <br />
            Read our{' '}
            <a
              target="_blank"
              rel="noopener noreferrer"
              className="Link--inTextBlock"
              href="https://docs.github.com/rest/overview/permissions-required-for-github-apps"
            >
              permissions documentation
            </a>{' '}
            for information about specific permissions.
          </p>
          {appMode === 'edit' && (
            <p data-view-component="true" className="mb-3">
              Changes to permissions will be applied to all future installations. Current users will be prompted to
              accept any changes and enable the new permissions on their installation.
            </p>
          )}
        </>
      )
    }
  }
  return (
    <>
      <div data-view-component="true" className="Subhead" {...testIdProps('permission-header')}>
        <h3 data-view-component="true" className="Subhead-heading Subhead-heading--large f3">
          Permissions
        </h3>
      </div>

      {getDescriptionText()}
    </>
  )
}

try{ PermissionHeader.displayName ||= 'PermissionHeader' } catch {}