import {Blankslate} from '@primer/react/experimental'
import {ListItem} from '@github-ui/list-view/ListItem'
import {PersonIcon, RepoIcon, OrganizationIcon, GlobeIcon} from '@primer/octicons-react'
import type {IconProps} from '@primer/octicons-react'
import type React from 'react'
import type {SectionName} from '../types/integration-permission-selector'
import {VisuallyHidden} from '@primer/react'

interface PermissionBlankSlateProps {
  section: SectionName
}

const blankSlateMetadata: Record<
  SectionName,
  {icon: React.ComponentType<IconProps>; heading: string; description: string}
> = {
  user: {
    icon: PersonIcon,
    heading: 'No account permissions added yet',
    description: 'User permissions permit access to resources under your personal GitHub account.',
  },
  repository: {
    icon: RepoIcon,
    heading: 'No repository permissions added yet',
    description: 'Repository permissions permit access to repositories and related resources.',
  },
  organization: {
    icon: OrganizationIcon,
    heading: 'No organization permissions added yet',
    description: 'Organization permissions permit access to organization related resources.',
  },
  business: {
    icon: GlobeIcon,
    heading: 'No enterprise permissions added yet',
    description: 'Enterprise permissions permit access to business related features and data.',
  },
}

export function PermissionBlankSlate({section}: PermissionBlankSlateProps) {
  const {icon: Icon, heading, description} = blankSlateMetadata[section]

  return (
    <ListItem
      title={<VisuallyHidden>Permission Blank Slate</VisuallyHidden>}
      style={{
        padding: 0,
        border: 'none',
        background: 'transparent',
        minHeight: '250px',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
      }}
    >
      <Blankslate size="small">
        <Blankslate.Visual>
          <Icon size="medium" />
        </Blankslate.Visual>
        <Blankslate.Heading>{heading}</Blankslate.Heading>
        <Blankslate.Description className="text-center">{description}</Blankslate.Description>
      </Blankslate>
    </ListItem>
  )
}

try{ PermissionBlankSlate.displayName ||= 'PermissionBlankSlate' } catch {}