import {Button} from '@primer/react'
import styles from './PermissionSelectorTab.module.css'
import {clsx} from 'clsx'

export interface PermissionSelectorTabProps {
  title: string
  isSelected?: boolean
  count: number
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void
}

export function PermissionSelectorTab({title, isSelected = false, count, onClick}: PermissionSelectorTabProps) {
  return (
    <Button
      as="button"
      variant="invisible"
      aria-current={isSelected ? 'true' : undefined}
      count={count}
      className={clsx(styles.container, isSelected && styles.selected)}
      onClick={onClick}
    >
      <div>{title}</div>
    </Button>
  )
}

try{ PermissionSelectorTab.displayName ||= 'PermissionSelectorTab' } catch {}